window.lookupMmd = function (skuName) {
  var key = String(skuName || "").trim().toLowerCase().replace(/\s+/g, " ");
  return window.MMD_MAPPING[key] || null;
};

/* Merge key for grouping trade SKUs that share one MMD Item Code into a single row. */
window.mmdGroup = function (skuName) {
  var m = window.lookupMmd(skuName);
  return m ? { key: "mmd:" + m.code, name: m.name, code: m.code } : { key: "sku:" + skuName, name: skuName, code: "" };
};
